<template>
  <section class="review-panel" :class="{ maximized }" role="dialog" aria-modal="true" aria-labelledby="git-review-title">
    <header class="review-titlebar" @dblclick="handleTitlebarDoubleClick">
      <div class="title-identity"><span class="app-icon"><Icon icon="solar:code-scan-linear" /></span><div><h2 id="git-review-title">代码审查</h2><p>本地优先 · 结构化结果 · SQLite 历史</p></div></div>
      <div class="window-actions"><button class="maximize-button" type="button" :title="maximized ? '还原窗口' : '最大化窗口'" :aria-label="maximized ? '还原窗口' : '最大化窗口'" @click.stop="toggleMaximized"><Icon :icon="maximized ? 'solar:minimize-square-3-linear' : 'solar:maximize-square-3-linear'" /></button><button class="close-button" type="button" aria-label="关闭" @click="$emit('close')"><span aria-hidden="true">×</span></button></div>
    </header>

    <div class="review-workspace">
      <aside class="review-sidebar">
        <button class="sidebar-primary" :class="{ active: view === 'new' }" type="button" @click="view = 'new'">
          <Icon icon="solar:add-circle-linear" /><span><strong>新建审查</strong><small>{{ selectedCount }} 个文件已选</small></span>
        </button>
        <div class="sidebar-label"><span>历史记录</span><em>{{ history.length }}</em></div>
        <div class="session-list">
          <button v-for="item in history" :key="item.id" class="session-row" :class="{ active: view === 'report' && session?.id === item.id }" type="button" @click="openHistory(item.id)">
            <i :class="`status-${item.status}`"></i><span><strong>{{ formatShortTime(item.createdAt) }}</strong><small>{{ item.selectedFileCount }} 个文件 · {{ statusLabel(item.status) }}</small></span><b v-if="item.overview.critical + item.overview.major">{{ item.overview.critical + item.overview.major }}</b>
          </button>
          <div v-if="!history.length" class="sidebar-empty">当前仓库还没有审查记录</div>
        </div>
        <button class="sidebar-rules" :class="{ active: view === 'rules' }" type="button" @click="view = 'rules'">
          <Icon icon="solar:tuning-2-linear" /><span>审查规则</span><em>{{ rules.length }}</em>
        </button>
      </aside>

      <main class="review-main">
        <section v-if="view === 'new'" class="content-screen">
          <header class="content-heading"><div><span>NEW REVIEW</span><h3>审查已勾选的变更</h3><p>关注度只帮助选择文件，AI 只会收到你明确勾选的 diff。</p></div></header>
          <div class="selection-summary" :class="{ empty: !selectedCount }"><span class="selection-icon"><Icon :icon="selectedCount ? 'solar:checklist-minimalistic-linear' : 'solar:folder-error-linear'" /></span><div><strong>{{ selectedCount ? `${selectedCount} 个文件已准备好` : '尚未选择文件' }}</strong><p>{{ selectedCount ? '返回文件列表可继续增减本次审查范围。' : '关闭此窗口，在变更列表中勾选文件后再开始；历史和规则仍可随时查看。' }}</p></div></div>
          <fieldset class="budget-picker" :disabled="running"><legend>上下文预算</legend><button v-for="option in budgetOptions" :key="option.value" :class="{ active: budget === option.value }" type="button" @click="budget = option.value"><span><strong>{{ option.label }}</strong><small>{{ option.description }}</small></span><i>{{ option.tokens }}</i></button></fieldset>
          <div v-if="!hasModel" class="notice danger"><Icon icon="solar:danger-triangle-linear" /><span>请先在模型设置中为“轻量 Review”配置可用模型。</span></div>
          <div v-if="error" class="notice danger"><Icon icon="solar:danger-triangle-linear" /><span>{{ error }}</span></div>
          <footer class="launch-actions"><span>确定性规则会先在本地运行，不消耗 Token。</span><button v-if="running" class="stop-icon-button" type="button" title="停止当前审查" aria-label="停止当前审查" @click="$emit('cancel')"><Icon icon="solar:stop-circle-linear" /></button><WorkbenchButton v-else variant="primary" :disabled="!selectedCount || !hasModel || loading" @click="startReview">{{ loading ? '正在启动…' : '开始审查' }}</WorkbenchButton></footer>
        </section>

        <section v-else-if="view === 'report'" class="content-screen report-screen">
          <div v-if="error && !session" class="content-empty"><Icon icon="solar:danger-triangle-linear" /><strong>无法打开审查</strong><p>{{ error }}</p><WorkbenchButton @click="view = 'new'">返回新建审查</WorkbenchButton></div>
          <div v-else-if="loading && !session" class="content-empty"><Icon icon="solar:refresh-circle-linear" /><strong>正在读取审查记录</strong></div>
          <template v-else-if="session">
            <header class="report-header"><div><span>{{ formatTime(session.createdAt) }}</span><h3>{{ statusLabel(session.status) }}</h3><p>{{ session.selectedFiles.length }} 个文件 · {{ budgetLabel(session.budgetMode) }} · {{ session.inputTokens + session.outputTokens }} Token{{ session.usageEstimated ? '（估算）' : '' }}</p></div><span class="status-badge" :class="`status-${session.status}`">{{ statusLabel(session.status) }}</span></header>
            <section v-if="running" class="progress-strip"><div><span>{{ progressLabel }}</span><em>{{ session.progressDone }}/{{ session.progressTotal }}</em></div><i><b :style="{ width: progressPercent + '%' }"></b></i><button class="stop-icon-button" type="button" title="停止当前审查" aria-label="停止当前审查" @click="$emit('cancel')"><Icon icon="solar:stop-circle-linear" /></button></section>
            <section class="severity-summary"><button v-for="item in severityOverview" :key="item.key" :class="[`severity-${item.key}`, { active: severityFilter === item.key }]" type="button" @click="toggleSeverity(item.key)"><strong>{{ item.value }}</strong><span>{{ item.label }}</span></button></section>
            <section class="finding-toolbar"><div class="segmented"><button v-for="item in statusFilters" :key="item.key" :class="{ active: findingStatus === item.key }" type="button" @click="findingStatus = item.key">{{ item.label }}<span>{{ item.count }}</span></button></div><span>{{ filteredFindings.length }} / {{ session.findings.length }}</span></section>
            <section v-if="filteredFindings.length" class="finding-list">
              <article v-for="finding in filteredFindings" :key="finding.id" class="finding-card" :class="`severity-${finding.severity}`">
                <header><span class="severity-dot"></span><div><strong>{{ finding.title }}</strong><button class="file-link" type="button" @click="$emit('open-file', finding.filePath)">{{ finding.filePath }}:{{ finding.startLine }}</button></div><span class="confidence">{{ Math.round(finding.confidence * 100) }}%</span></header>
                <dl><div><dt>问题</dt><dd>{{ finding.problem }}</dd></div><div><dt>影响</dt><dd>{{ finding.impact }}</dd></div><div><dt>触发</dt><dd>{{ finding.triggerScenario }}</dd></div><div><dt>证据</dt><dd><code>{{ finding.evidence }}</code></dd></div><div v-if="finding.suggestion"><dt>建议</dt><dd>{{ finding.suggestion }}</dd></div></dl>
                <footer><span>{{ finding.source === 'deterministic' ? '本地规则' : 'AI 审查' }} · {{ finding.category }}</span><div><button type="button" :class="{ active: finding.status === 'confirmed' }" @click="$emit('finding-status', finding.id, 'confirmed')">确认</button><button type="button" :class="{ active: finding.status === 'ignored' }" @click="$emit('finding-status', finding.id, 'ignored')">忽略</button><button type="button" :class="{ active: finding.status === 'fixed' }" @click="$emit('finding-status', finding.id, 'fixed')">已修复</button></div></footer>
              </article>
            </section>
            <section v-else class="content-empty compact"><Icon icon="solar:check-circle-linear" /><strong>{{ session.findings.length ? '没有符合当前筛选的发现' : '没有发现可确认的问题' }}</strong><p>仍建议检查审查范围和下方诊断信息。</p></section>
            <details v-if="diagnosticItems.length" class="detail-panel" open><summary><span><Icon icon="solar:info-circle-linear" />诊断与限制</span><em>{{ diagnosticItems.length }}</em></summary><ul><li v-for="item in diagnosticItems" :key="item" :class="{ danger: item.includes('审查失败') || item.includes('返回了空内容') || item.includes('被截断') }">{{ item }}</li></ul></details>
            <details v-if="session.files.length" class="detail-panel file-panel"><summary><span><Icon icon="solar:documents-linear" />审查文件</span><em>{{ session.files.length }}</em></summary><button v-for="file in session.files" :key="file.path" type="button" @click="$emit('open-file', file.path)"><span><strong>{{ file.path }}</strong><small>{{ file.scoreCategories.join(' · ') || '常规变更' }}<template v-if="file.limitation"> · {{ file.limitation }}</template></small></span><b>{{ file.attentionScore }}</b></button></details>
          </template>
          <div v-else class="content-empty"><Icon icon="solar:history-linear" /><strong>选择一条审查记录</strong><p>历史记录保存在本地 SQLite，不需要先勾选文件。</p></div>
        </section>

        <section v-else class="content-screen">
          <header class="content-heading"><div><span>REVIEW RULES</span><h3>自定义审查规则</h3><p>确定性规则在本地运行；语义规则仅发送给匹配文件。</p></div><WorkbenchButton @click="resetRule">新建规则</WorkbenchButton></header>
          <div class="rule-form"><label><span>名称</span><NInput v-model:value="draft.name" size="small" placeholder="例如：禁止直接访问 localStorage" /></label><label><span>类型</span><NSelect v-model:value="draft.kind" size="small" :options="ruleKindOptions" /></label><label><span>严重度</span><NSelect v-model:value="draft.severity" size="small" :options="severityOptions" /></label><label class="wide"><span>文件范围</span><NInput v-model:value="draft.includeGlobsText" size="small" placeholder="src/*.ts, src/**" /></label><label class="wide"><span>{{ draft.kind === 'semantic' ? '审查要求' : '匹配内容' }}</span><NInput v-model:value="draft.pattern" type="textarea" :autosize="{ minRows: 3, maxRows: 7 }" :placeholder="draft.kind === 'semantic' ? '用具体、可验证的语言描述风险' : '新增行需要匹配的文本'" /></label><footer class="wide"><NCheckbox v-model:checked="draft.enabled">启用</NCheckbox><WorkbenchButton variant="primary" :disabled="!draft.name.trim() || !draft.pattern.trim()" @click="saveDraft">保存规则</WorkbenchButton></footer></div>
          <div class="rule-list"><article v-for="rule in rules" :key="rule.id"><button type="button" @click="editRule(rule)"><span><strong>{{ rule.name }}</strong><small>{{ rule.kind === 'semantic' ? '语义规则' : '本地规则' }} · {{ severityLabel(rule.severity) }} · v{{ rule.version }}</small></span><em :class="{ enabled: rule.enabled }">{{ rule.enabled ? '启用' : '停用' }}</em></button><button class="delete-rule" type="button" @click="$emit('delete-rule', rule.id)">删除</button></article><div v-if="!rules.length" class="content-empty compact"><strong>还没有自定义规则</strong></div></div>
        </section>
      </main>
    </div>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import { NCheckbox, NInput, NSelect } from 'naive-ui'
import type { ReviewBudgetMode, ReviewFindingStatus, ReviewRule, ReviewSession, ReviewSessionSummary } from '@/types/review'
import { hasPrimaryModifier } from '@/utils/platform-shortcuts'
import WorkbenchButton from '@/components/workbench/WorkbenchButton.vue'

const props = defineProps<{ session: ReviewSession | null; history: ReviewSessionSummary[]; rules: ReviewRule[]; selectedCount: number; hasModel: boolean; running: boolean; loading: boolean; error: string }>()
const emit = defineEmits<{ close: []; start: [mode: ReviewBudgetMode]; cancel: []; 'open-session': [id: string]; 'open-file': [path: string]; 'finding-status': [id: string, status: ReviewFindingStatus]; 'save-rule': [rule: ReviewRule]; 'delete-rule': [id: string] }>()
const view = ref<'new' | 'report' | 'rules'>(props.running ? 'report' : props.selectedCount ? 'new' : 'report')
const maximized = ref(false)
const budget = ref<ReviewBudgetMode>('compact')
const severityFilter = ref('')
const findingStatus = ref<'all' | ReviewFindingStatus>('all')
const budgetOptions: Array<{ value: ReviewBudgetMode; label: string; description: string; tokens: string }> = [{ value: 'compact', label: '精简', description: '优先明显缺陷，速度最快', tokens: '≤ 24k 字符' }, { value: 'standard', label: '标准', description: '补充跨文件上下文', tokens: '≤ 48k 字符' }, { value: 'deep', label: '深入', description: '适合复杂链路人工复核', tokens: '≤ 96k 字符' }]
const ruleKindOptions = [{ label: '确定性规则（0 Token）', value: 'deterministic' }, { label: '语义规则（AI）', value: 'semantic' }]
const severityOptions = ['critical', 'major', 'minor', 'suggestion'].map(value => ({ label: severityLabel(value), value }))
const progressPercent = computed(() => props.session?.progressTotal ? Math.round(props.session.progressDone / props.session.progressTotal * 100) : 0)
const progressLabel = computed(() => props.session?.currentFile ? `正在审查 ${props.session.currentFile}` : props.session?.phase === 'ai-review' ? '正在等待模型返回结构化结果' : '正在准备审查上下文')
const severityOverview = computed(() => { const overview = props.session?.overview; return [{ key: 'critical', label: '严重', value: overview?.critical ?? 0 }, { key: 'major', label: '主要', value: overview?.major ?? 0 }, { key: 'minor', label: '次要', value: overview?.minor ?? 0 }, { key: 'suggestion', label: '建议', value: overview?.suggestion ?? 0 }] })
const statusFilters = computed(() => { const findings = props.session?.findings ?? []; return [{ key: 'all' as const, label: '全部', count: findings.length }, { key: 'open' as const, label: '待处理', count: findings.filter(item => item.status === 'open').length }, { key: 'confirmed' as const, label: '已确认', count: findings.filter(item => item.status === 'confirmed').length }, { key: 'fixed' as const, label: '已修复', count: findings.filter(item => item.status === 'fixed').length }, { key: 'ignored' as const, label: '已忽略', count: findings.filter(item => item.status === 'ignored').length }] })
const filteredFindings = computed(() => (props.session?.findings ?? []).filter(item => (!severityFilter.value || item.severity === severityFilter.value) && (findingStatus.value === 'all' || item.status === findingStatus.value)))
const diagnosticItems = computed(() => {
  const session = props.session
  if (!session) return []
  const items = [...session.limitations]
  for (const call of session.aiCalls.filter(item => item.error)) {
    if (!items.some(item => item.includes(call.error || ''))) items.push(`${call.batchId} 审查失败: ${call.error}`)
  }
  return items
})
const draft = reactive({ id: '', name: '', kind: 'deterministic' as ReviewRule['kind'], severity: 'major' as ReviewRule['severity'], includeGlobsText: '**', pattern: '', enabled: true })
function severityLabel(value: string) { return ({ critical: '严重', major: '主要', minor: '次要', suggestion: '建议' } as Record<string, string>)[value] || value }
function statusLabel(value: string) { return ({ running: '审查中', completed: '已完成', partial: '部分完成', failed: '失败', cancelled: '已停止', interrupted: '已中断' } as Record<string, string>)[value] || value }
function budgetLabel(value: string) { return ({ compact: '精简', standard: '标准', deep: '深入' } as Record<string, string>)[value] || value }
function formatTime(value: number) { return new Date(value).toLocaleString() }
function formatShortTime(value: number) { const date = new Date(value); return `${date.toLocaleDateString([], { month: '2-digit', day: '2-digit' })} ${date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}` }
function openHistory(id: string) { view.value = 'report'; severityFilter.value = ''; findingStatus.value = 'all'; emit('open-session', id) }
function startReview() { view.value = 'report'; emit('start', budget.value) }
function toggleMaximized() { maximized.value = !maximized.value }
function handleTitlebarDoubleClick(event: MouseEvent) { if (!(event.target instanceof Element) || !event.target.closest('button')) toggleMaximized() }
function toggleSeverity(value: string) { severityFilter.value = severityFilter.value === value ? '' : value }
function resetRule() { Object.assign(draft, { id: '', name: '', kind: 'deterministic', severity: 'major', includeGlobsText: '**', pattern: '', enabled: true }) }
function editRule(rule: ReviewRule) { Object.assign(draft, { id: rule.id, name: rule.name, kind: rule.kind, severity: rule.severity, includeGlobsText: rule.includeGlobs.join(', '), pattern: String(rule.definition.pattern || rule.definition.instruction || ''), enabled: rule.enabled }) }
function saveDraft() { const id = draft.id || `custom.${Date.now()}`; emit('save-rule', { id, name: draft.name.trim(), description: null, kind: draft.kind, enabled: draft.enabled, severity: draft.severity, category: 'custom', includeGlobs: draft.includeGlobsText.split(',').map(item => item.trim()).filter(Boolean), excludeGlobs: [], languages: [], definition: draft.kind === 'semantic' ? { instruction: draft.pattern.trim() } : { target: 'added-lines', operator: 'contains', pattern: draft.pattern.trim() }, source: 'global', version: 1 }); resetRule() }
function handleShortcut(event: KeyboardEvent) { if (event.key === 'Escape') { emit('close'); return } if (view.value === 'new' && hasPrimaryModifier(event) && event.key === 'Enter' && !props.running && props.selectedCount && props.hasModel) { event.preventDefault(); startReview() } }
onMounted(() => window.addEventListener('keydown', handleShortcut)); onUnmounted(() => window.removeEventListener('keydown', handleShortcut))
</script>

<style scoped lang="scss">
