.review-titlebar{align-items:center;background:var(--lumina-toolbar-bg);backdrop-filter:saturate(180%) blur(24px);border-bottom:.5px solid var(--lumina-separator);display:flex;justify-content:space-between;padding:7px 12px 7px 14px;user-select:none}.title-identity{align-items:center;display:flex;gap:10px}.title-identity h2{font-size:14px;font-weight:600;margin:0}.title-identity p{color:var(--lumina-text-secondary);font-size:10px;margin:1px 0 0}.app-icon{align-items:center;background:color-mix(in srgb,var(--lumina-primary) 12%,var(--lumina-surface-2));border-radius:8px;color:var(--lumina-primary);display:flex;height:32px;justify-content:center;width:32px}.app-icon svg{height:17px;width:17px}.window-actions{align-items:center;display:flex;gap:2px}.maximize-button,.close-button{align-items:center;background:transparent;border:0;border-radius:6px;color:var(--lumina-text-secondary);cursor:pointer;display:flex;height:28px;justify-content:center;padding:0;width:28px}.maximize-button svg{height:15px;width:15px}.close-button{font-size:20px;font-weight:300}.maximize-button:hover,.close-button:hover{background:var(--lumina-control-hover);color:var(--lumina-text)}.maximize-button:focus-visible,.close-button:focus-visible{box-shadow:0 0 0 3px var(--lumina-accent-ring);outline:none}
